      BoxShadow(color: Color(0x170B1B33), offset: Offset(0.0, 8.0), blurRadius: 24.0),
      BoxShadow(color: Color(0x0D0B1B33), offset: Offset(0.0, 2.0), blurRadius: 4.0),
    ],
    // 0 -1px 0 #0b1b330f, 0 -8px 24px #0b1b330f
