      BoxShadow(color: Color(0x0F0B1B33), offset: Offset(0.0, -8.0), blurRadius: 24.0),
      BoxShadow(color: Color(0x0F0B1B33), offset: Offset(0.0, -1.0)),
    ],
    // 0 8px 16px #0b1b3314, 0 24px 56px #0b1b3329
