      BoxShadow(color: Color(0x290B1B33), offset: Offset(0.0, 24.0), blurRadius: 56.0),
      BoxShadow(color: Color(0x140B1B33), offset: Offset(0.0, 8.0), blurRadius: 16.0),
    ],
    // 0 0 0 2px #ffffff, 0 0 0 4px #0b1b33
