      BoxShadow(color: Color(0xFF0B1B33), spreadRadius: 4.0),
      BoxShadow(color: Color(0xFFFFFFFF), spreadRadius: 2.0),
    ],
    shadowColor: Color(0xFF0B1B33),
  );

  /// Night match.
  static const MuElevation dark = MuElevation._(
    // 0 0 0 1px #ffffff0a
    level1: <BoxShadow>[
      BoxShadow(color: Color(0x0AFFFFFF), spreadRadius: 1.0),
    ],
    // 0 0 0 1px #ffffff12, 0 8px 24px #00000052
